module trash_game(input clk, input rst_n, input start, input [415:0] deck, output reg result, output reg done); reg [3:0] theta_slots [0:9]; reg [3:0] friend_slots [0:9]; reg [13:0] theta_revealed; reg [13:1] friend_revealed; reg [5:0] deck_ptr; reg [3:0] current_card; reg [5:0] turn_count; reg current_player; reg [7:0] state; localparam IDLE = 3'd0; localparam CHECK_WIN = 3'd1; localparam DRAW_CARD = 3'd2; localparam THETA_JACK_STRATEGY = 3'd3; localparam FRIEND_JACK_STRATEGY = 3'd4; localparam PLACE_CARD = 3'd5; localparam DISCARD_TURN = 3'd6; localparam SWITCH_PLAYER = 3'd7; localparam WIN = 3'd8; always @(negedge rst_n) begin if (!rst_n) begin deck_ptr <= 20; turn_count <= 0; current_player <= 0; state <= IDLE; theta_slots <= 0; friend_slots <= 0; theta_revealed <= 0; friend_revealed <= 0; end end end always @(posedge clk) begin if (state == IDLE) begin if (start) state <= CHECK_WIN; end end end assign result = 0; assign done = 0; endmodule